import * as React from "react";
import "@fontsource/shrikhand";
import "@fontsource/cabin";
import "@fontsource/fira-sans";

const h1 = {
  fontFamily: "shrikhand",
  fontWeight: 100,
  marginBottom: 0,
  marginTop: 0,
};

const p = {
  fontFamily: "cabin",
  marginTop: 0,
  marginBottom: "1em",
};

const ParkVolunteerism = () => {
  return (
    <div style={{ width: "95%" }}>
      <h1 style={h1}>Park Volunteerism</h1>
      <p style={{ ...p, width: "90%" }}>
        I care deeply about public spaces, neighborhood stewardship, and the
        small things that make a community feel welcoming. Whether it's helping
        with cleanup days, supporting local greenspace projects, or showing up
        for seasonal volunteer events, I believe a healthy park is a shared
        responsibility.
      </p>
      <hr />
      <div style={{ display: "flex", flexDirection: "column", gap: "1em" }}>
        <div>
          <h4 style={{ ...h1, marginBottom: 0 }}>Stewardship</h4>
          <p style={p}>
            I volunteer to help keep trails, gathering spaces, and community
            parks clean, accessible, and welcoming for everyone.
          </p>
        </div>
        <div>
          <h4 style={{ ...h1, marginBottom: 0 }}>Community</h4>
          <p style={p}>
            I value organizations that bring neighbors together around shared
            spaces and meaningful local action.
          </p>
        </div>
        <div>
          <h4 style={{ ...h1, marginBottom: 0 }}>Care for the Outdoors</h4>
          <p style={p}>
            Nature is part of daily life, and I try to contribute in practical,
            hands-on ways that improve the experience for the people around me.
          </p>
        </div>
      </div>
    </div>
  );
};

export default ParkVolunteerism;
